<template>
  <div class="mobile-empty-state">
    <mobile-l-img v-if="iconSrc" :src="iconSrc" :w="iconSize" :h="iconSize" class="empty-icon" />
    <div v-if="title" class="empty-title">{{ title }}</div>
    <div v-if="message || errorMessage" class="empty-message">
      {{ message || errorMessage }}
    </div>
    <div v-if="actionText" class="empty-action" @click="handleAction">
      {{ actionText }}
    </div>
  </div>
</template>

<script setup>
import { computed } from 'vue';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
// Props
const props = defineProps({
  type: {
    type: String,
    required: true,
    validator: (value) => ['no-login', 'error', 'no-data'].includes(value)
  },
  title: { type: String, default: '' },
  message: { type: String, default: '' },
  errorMessage: { type: String, default: '' },
  actionText: { type: String, default: '' }
});

// Emits
const emit = defineEmits(['action']);

// 计算属性
const iconSrc = computed(() => {
  switch (props.type) {
    case 'error':
      return '/static/images/error_file_icon.png';
    case 'no-data':
      return '/static/images/conversation/chat_empty_icon.png';
    default:
      return null;
  }
});

const iconSize = computed(() => {
  switch (props.type) {
    case 'error':
      return '60px';
    case 'no-data':
      return '80px';
    default:
      return '60px';
  }
});

// 方法
const handleAction = () => {
  emit('action');
};
</script>

