import { ref, type Ref } from 'vue';

// 类型定义
interface Position {
  x: number;
  y: number;
}

interface Conversation {
  id: string | number;
  title: string;
  [key: string]: any;
}

interface MenuDimensions {
  width: number;
  height: number;
  padding: number;
}

interface UseLongPressMenuReturn {
  // 状态
  contextMenuVisible: Ref<boolean>;
  contextMenuPosition: Ref<Position>;
  contextMenuConversation: Ref<Conversation | null>;
  longPressConversation: Ref<Conversation | null>;
  isScrolling: Ref<boolean>;
  
  // 方法
  showContextMenu: (conversation: Conversation, position: Position) => void;
  hideContextMenu: () => void;
  setLongPressConversation: (conversation: Conversation | null) => void;
  setScrolling: (scrolling: boolean) => void;
  isLongPressingConversation: (conversationId: string | number) => boolean;
}

export function useLongPressMenu(): UseLongPressMenuReturn {
  // 状态变量
  const contextMenuVisible: Ref<boolean> = ref<boolean>(false);
  const contextMenuPosition: Ref<Position> = ref<Position>({ x: 0, y: 0 });
  const contextMenuConversation: Ref<Conversation | null> = ref<Conversation | null>(null);
  const longPressConversation: Ref<Conversation | null> = ref<Conversation | null>(null);
  const isScrolling: Ref<boolean> = ref<boolean>(false);

  // 菜单尺寸配置
  const MENU_DIMENSIONS: MenuDimensions = {
    width: 250,
    height: 132, // 3个菜单项 * 44px高度
    padding: 20  // 距离屏幕边缘的最小距离
  };

  // 计算安全的菜单位置
  const calculateSafePosition = (position: Position): Position => {
    const { width: menuWidth, height: menuHeight, padding } = MENU_DIMENSIONS;
    
    let x: number = position.x;
    let y: number = position.y;
    
    // 确保弹窗不超出屏幕右边界
    if (x + menuWidth / 2 > window.innerWidth - padding) {
      x = window.innerWidth - menuWidth / 2 - padding;
    }
    
    // 确保弹窗不超出屏幕左边界
    if (x - menuWidth / 2 < padding) {
      x = menuWidth / 2 + padding;
    }
    
    // 确保弹窗不超出屏幕下边界
    if (y + menuHeight / 2 > window.innerHeight - padding) {
      y = window.innerHeight - menuHeight / 2 - padding;
    }
    
    // 确保弹窗不超出屏幕上边界
    if (y - menuHeight / 2 < padding) {
      y = menuHeight / 2 + padding;
    }
    
    return { x, y };
  };

  // 触觉反馈
  const triggerHapticFeedback = (): void => {
    if (navigator.vibrate) {
      navigator.vibrate(50);
    }
  };

  // 显示上下文菜单
  const showContextMenu = (conversation: Conversation, position: Position): void => {
    contextMenuConversation.value = conversation;
    
    // 计算安全位置
    const safePosition = calculateSafePosition(position);
    contextMenuPosition.value = safePosition;
    contextMenuVisible.value = true;

    // 添加触觉反馈
    triggerHapticFeedback();

    console.log('Long press triggered for conversation:', conversation.title);
  };

  // 隐藏上下文菜单
  const hideContextMenu = (): void => {
    contextMenuVisible.value = false;
    contextMenuConversation.value = null;
    longPressConversation.value = null;
  };

  // 设置长按会话
  const setLongPressConversation = (conversation: Conversation | null): void => {
    longPressConversation.value = conversation;
  };

  // 设置滚动状态
  const setScrolling = (scrolling: boolean): void => {
    isScrolling.value = scrolling;
  };

  // 检查是否正在长按某个会话
  const isLongPressingConversation = (conversationId: string | number): boolean => {
    return longPressConversation.value?.id === conversationId;
  };

  return {
    // 状态
    contextMenuVisible,
    contextMenuPosition,
    contextMenuConversation,
    longPressConversation,
    isScrolling,
    
    // 方法
    showContextMenu,
    hideContextMenu,
    setLongPressConversation,
    setScrolling,
    isLongPressingConversation
  };
} 